function git(string $root, array $args): array
{
    $process = proc_open(
        ['git', '--literal-pathspecs', '-C', $root, ...$args],
        [1 => ['pipe', 'w'], 2 => ['pipe', 'w']],
        $pipes,
    );
    if ($process === false) {
        return [-1, ''];
    }
    $stdout = (string) stream_get_contents($pipes[1]);
    stream_get_contents($pipes[2]);
    fclose($pipes[1]);
    fclose($pipes[2]);

    return [proc_close($process), trim($stdout)];
}

